INSERT INTO world.trainer (Id, Type, Greeting, VerifiedBuild) VALUES (60023, 0, '', 0);
INSERT IGNORE INTO world.trainer_spell (TrainerId, SpellId, MoneyCost, ReqSkillLine, ReqSkillRank, ReqAbility1, ReqAbility2, ReqAbility3, ReqLevel, VerifiedBuild) SELECT 60023, IF(s.effect1 = 36 AND s.effectTriggerSpell1 > 0, s.effectTriggerSpell1, t.spell), t.spellcost, t.reqskill, t.reqskillvalue, COALESCE(c.prev_spell, 0), 0, 0, t.reqlevel, 0 FROM vmangos_world.npc_trainer_template t LEFT JOIN vmangos_world.ns_spell s ON s.entry = t.spell LEFT JOIN (SELECT spell_id, ANY_VALUE(prev_spell) AS prev_spell FROM vmangos_world.spell_chain WHERE build_min <= 5875 AND build_max >= 5875 GROUP BY spell_id) c ON c.spell_id = IF(s.effect1 = 36 AND s.effectTriggerSpell1 > 0, s.effectTriggerSpell1, t.spell) WHERE t.entry = 23 AND t.build_min <= 5875 AND t.build_max >= 5875;
